content.text:
{
  "name": "NI数字输出设备",
  "name_en": "NI Digital Output Device",
  "manufacturer": "National Instruments",
  "description": "这是一类美国国家仪器公司的数字输出数据采集设备或板卡，可通过多个数字通道输出高低电平信号，用于实验室中的TTL控制、设备触发、开关量控制和自动化联动。",
  "description_en": "This is a National Instruments digital output data acquisition device or board that provides multiple digital channels for outputting logic high/low signals, commonly used in laboratories for TTL control, instrument triggering, on/off switching, and automation interlocks.",
  "tag_hints": [
    "digital output",
    "NI-DAQmx",
    "TTL control",
    "DAQ",
    "instrument triggering",
    "switching signals",
    "lab automation"
  ],
  "actions": [
    {
      "action_name": "auto-setup",
      "description": "初始化数字输出设备的配置参数。",
      "description_en": "Initialize the digital output device configuration parameters."
    },
    {
      "action_name": "auto-connect",
      "description": "连接到NI数字输出硬件。",
      "description_en": "Connect to the NI digital output hardware."
    },
    {
      "action_name": "auto-disconnect",
      "description": "断开与NI数字输出硬件的连接。",
      "description_en": "Disconnect from the NI digital output hardware."
    },
    {
      "action_name": "auto-write_value",
      "description": "向数字输出通道写入电平值或开关状态。",
      "description_en": "Write a logic level or switching state to the digital output channels."
    },
    {
      "action_name": "auto-update_channels",
      "description": "扫描并更新可用的NI设备及其数字输出通道。",
      "description_en": "Scan and update the available NI devices and their digital output channels."
    }
  ]
}

